/**
 * 「数列の極限」ユニットの系列（数Ⅲ・C 第2章）。
 *
 * 背骨設計は docs/math3c_limits_design.md
 * （メイン Opus 5・2026-08-26・裁定 → Round 1 背骨監査 → 全件反映 → 凍結）。
 * 系列1（お手本）はメインが実装し、系列2〜10 は並列委譲＋メイン検収（C15）。
 *
 * 出典: 池田洋介『数学Ⅲ・C 入門問題精講』第2章 数列の極限（旺文社・2024）の
 * 章構成を借り、問題の値・場面はすべてオリジナルに変更（copyright-credit-vs-copy）。
 *
 * ハブ胚細胞（背骨 D1）：
 *   数Ⅱ・B まで、数列に対して私たちがしていたのは「捕まえる」ことだった——
 *   一般項という式に閉じ込め、和の公式で畳み、帰納法で覆う。どれも有限の手つきである。
 *   ここで相手が変わる。問うのは行き先であり、しかも「無限個の足し算」という、
 *   そもそも実行できない操作の結果を言い切ろうとする。
 *   できるのは、有限で実行できるもの——部分和・大小のはさみ・書き換え——を並べ、
 *   その極限として「答え」を定義し直すことだけである。
 *
 * 入力の折り方（背骨 D2・入力系の拡張は不要＝実運用7例目）：
 * - 発散（∞・−∞・振動）は答えにしない。原典 p.34 自身が「∞ は値ではない」と書いている。
 *   「収束するものの個数」「振動するものの個数」へ折る。個数檻の母集団は 4〜5（2・3 は使わない）
 * - 収束条件の範囲（−1<r<1）は両端を別 step に割らない（C1 追補9）
 * - 入口（基／同）の提出値を 0 にしない。0 は直前の非零 step との対比が立つ位置にだけ置く
 * - 提出値が「教える結論だけから言えてしまう」step を作らない（Round 1 監査の還流）
 */

